function renderTasks(list,title){const p=panel(title),b=table(p,['Task','Student / Section','Assigned staff','Due','Status / outcome','Action']);for(const[id,t]of list.sort((a,b)=>a[1].due.localeCompare(b[1].due))){const row=el('tr');cell(row,t.title);const linked=cell(row,'');if(people()[t.studentKey])linked.append(button(people()[t.studentKey].name,()=>go({student:t.studentKey})));else linked.textContent=t.sectionKey||'General';cell(row,'').append(button(staffName(t.staffId),()=>go({staff:t.staffId})));cell(row,t.due);cell(row,`${t.status}${!['done','cancelled'].includes(t.status)&&t.due<today()?' · OVERDUE':''}${t.outcome?' · '+t.outcome:''}`);cell(row,'').append(button('Edit',()=>editTask(id)),button('Remove',()=>remove('tasks',id)));b.append(row);}if(!list.length)p.append(el('p','No actions recorded.','muted'));}
