function field(name,label,value='',{type='text',required=false,max=200,step,min,maximum}={}){const wrap=el('label',label),input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.name=name;input.value=value;input.required=required;input.maxLength=max;if(step)input.step=step;if(min!==undefined)input.min=min;if(maximum!==undefined)input.max=maximum;wrap.append(input);$('mission-fields').append(wrap);return input;}
