function editor(title,setup,onSave){if(!editable()||busy)return;editorRevision=mission.revision;editorSave=onSave;$('mission-editor-title').textContent=title;$('mission-fields').replaceChildren();$('mission-editor-error').hidden=true;setup();$('mission-editor').showModal();}
async function save(next,expected=mission?.revision){if(!editable()||busy)throw Error('Wait for the current save or sign in.');validateMission(next,draft,faculty);const token=generation;busy=true;document.documentElement.dataset.portalBusy='true';$('mission-save').disabled=true;try{const result=await api.runTransaction(api.ref(db,'cbse/mission'),current=>{if((current?.revision||0)!==expected)return;return {...next,revision:expected+1,updatedAt:Date.now()};},{applyLocally:false});if(!result.committed)throw Error('Mission data changed in another session. Close this form and review the latest data before trying again.');if(token!==generation)return false;mission=result.snapshot.val();render();message('Mission record saved privately.','success');return true;}finally{busy=false;document.documentElement.dataset.portalBusy='false';$('mission-save').disabled=false;}}
