$('mission-form').onsubmit=async e=>{e.preventDefault();try{if(!mission||mission.revision!==editorRevision)throw Error('Data changed while the form was open. Close and reopen the form.');if(await editorSave(new FormData(e.target))===false)return;$('mission-editor').close();$('mission-fields').replaceChildren();}catch(error){$('mission-editor-error').textContent=error.message;$('mission-editor-error').hidden=false;}};
