function matches(text,query){const normalise=value=>String(value).toLowerCase().replace(/[^a-z0-9\u0080-\uffff]+/g,' ').trim();const hay=normalise(text),q=normalise(query).replace(/\b(xii|x)([a-z])\b/g,'$1 $2');if(!q)return true;return q.split(' ').every(token=>token.length<=2?hay.split(' ').includes(token):hay.includes(token));}
