function renderDetailFields(kind,values){let box=$('monitor-detail-fields');if(!box){box=el('fieldset');box.id='monitor-detail-fields';$('mission-fields').append(box);}box.replaceChildren();const fields=DETAIL_FIELDS[kind]||[];box.hidden=!fields.length;if(!fields.length)return;box.append(el('legend','Monitoring details'));for(const[key,label,type,choices]of fields){const wrap=el('label',label);let input;if(type==='select'){input=el('select');options(input,[['','Not recorded'],...choices.map(v=>[v,v.replaceAll('_',' ')])],values[key]||'');}else{input=el(type==='textarea'?'textarea':'input');if(type!=='textarea')input.type=type;input.value=values[key]??'';if(type==='number'){input.min=0;input.max=1000;input.step=1;}else input.maxLength=type==='textarea'?1500:300;}if(type==='select'&&key==='status'&&kind==='remedial')input.required=true;input.name='detail_'+key;wrap.append(input);box.append(wrap);}}
function readDetailFields(form,kind){const details={};for(const[key,,type]of DETAIL_FIELDS[kind]||[]){const value=form.get('detail_'+key);if(value===null||value==='')continue;details[key]=type==='number'?Number(value):String(value).trim();}return details;}
function renderMonitoringTiles(){const p=panel('Teaching & support monitoring');p.append(el('p',editable()?'Open a dedicated area, choose a teacher and review the complete support picture.':'Explore the monitoring areas. Private records and feeding open with authorised access.','muted'));const grid=el('div',undefined,'monitor-grid');for(const[id,area]of entries(MONITOR_AREAS)){const tile=button('',()=>go({tab:id}));tile.className='monitor-tile';tile.append(el('span',area.icon,'monitor-icon'),el('strong',area.title),el('small',area.description));grid.append(tile);}const timetable=button('',()=>go({tab:'timetable'}));timetable.className='monitor-tile';timetable.append(el('span','◷','monitor-icon'),el('strong','Break-time timetable'),el('small','Teacher, class, time and room—with clash checks.'));grid.append(timetable);p.append(grid);}
function renderMonitoringArea(tab){const area=MONITOR_AREAS[tab],p=panel(area.title);p.append(el('p',area.description,'muted'));const controls=el('div',undefined,'actions');
 if(tab==='teachers'){controls.append(button('Record classroom observation',()=>editRecord(null,'','','observation'),true),button('Record other effort',()=>editRecord(null,'','','effort')),button('Break / remedial timetable',()=>go({tab:'timetable'})));p.append(controls);renderMonitoringTiles();renderTeacherDirectory();return;}
 controls.append(button(tab==='remedial'?'Add remedial session':tab==='worksheets'?'Add worksheet / practice record':tab==='ct'?'Add CT / Co-CT review':tab==='counselling'?'Add counselling follow-up':tab==='prt'?'Add PRT support record':'Add weekly review',()=>editRecord(null,'','',area.kind),true),button('Assign follow-up task',()=>editTask(null,'','',area.kind)),button('Teacher directory',()=>go({tab:'teachers'})));p.append(controls);
 const filters=el('div',undefined,'filters'),staffLabel=el('label','Teacher / support member'),teacher=el('select'),classLabel=el('label','Class'),cl=el('select'),dateLabel=el('label','Records from'),from=el('input');teacher.setAttribute('aria-label','Monitoring teacher');cl.setAttribute('aria-label','Monitoring class');from.type='date';from.setAttribute('aria-label','Monitoring from date');options(teacher,[['','All staff'],...staffOptions().filter(([id])=>id)],'');options(cl,[['','Both standards'],['X','Class X'],['XII','Class XII']],'');staffLabel.append(teacher);classLabel.append(cl);dateLabel.append(from);filters.append(staffLabel,classLabel,dateLabel);p.append(filters);
 const content=el('div');$('mission-view').append(content);
 const draw=()=>{content.replaceChildren();const matchesScope=r=>{if(teacher.value&&r.staffId!==teacher.value)return false;const person=people()[r.studentKey],standard=person?.classId||r.sectionKey?.split(':')[0]||staff()[r.staffId]?.classId;return (!cl.value||standard===cl.value)&&(!from.value||r.date>=from.value);};const kinds=tab==='weekly'?['weekly','effort']:[area.kind];const rows=entries(mission.records).filter(([,r])=>kinds.includes(r.kind)&&matchesScope(r));const numbers=el('div',undefined,'stats');stats(numbers,[[rows.length,'Records'],[rows.filter(([,r])=>r.details?.status==='conducted'||r.details?.status==='checked'||r.details?.status==='reviewed').length,'Conducted / reviewed'],[rows.filter(([,r])=>r.details?.nextReview&&r.details.nextReview<today()).length,'Review dates passed']]);content.append(numbers);renderRecords(rows,tab==='remedial'?'Remedial session register':tab==='worksheets'?'Worksheet & practice register':'Monitoring register');const register=$('mission-view').lastElementChild;content.append(register);};teacher.onchange=draw;cl.onchange=draw;from.onchange=draw;draw();
 if(tab==='ct')renderClassTeacherWatch();
 if(tab==='counselling'||tab==='prt'){const members=panel(tab==='counselling'?'Counsellor team':'Primary support partners');members.append(button('Manage support-team members',()=>go({tab:'support'})));for(const[id,s]of entries(staff()).filter(([,s])=>s.kind===(tab==='counselling'?'counsellor':'prt')))members.append(button(s.name,()=>go({staff:id})));}
}
function renderTeacherDirectory(){const p=panel('Teacher profiles · X & XII'),filters=el('div',undefined,'filters'),search=el('input'),cl=el('select');search.type='search';search.placeholder='Find a teacher by name, subject or section';search.setAttribute('aria-label','Search teacher profiles');options(cl,[['','Both standards'],['X','Class X'],['XII','Class XII']],'');cl.setAttribute('aria-label','Teacher directory class');filters.append(search,cl);p.append(filters);const cards=el('div',undefined,'student-cards');p.append(cards);const draw=()=>{cards.replaceChildren();for(const[id,t]of entries(staff()).filter(([,t])=>t.kind==='faculty'&&(!cl.value||t.classId===cl.value)&&matches(`${t.name} ${t.designation} ${t.subjects} ${t.teachingSections}`,search.value))){const card=button('',()=>go({staff:id}));card.className='student-card';card.setAttribute('aria-label','Teacher profile: '+t.name);const text=el('span',undefined,'student-card-copy'),records=entries(mission.records).filter(([,r])=>r.staffId===id),tasks=entries(mission.tasks).filter(([,r])=>r.staffId===id&&!['done','cancelled'].includes(r.status));text.append(el('strong',t.name),el('small',`${t.classId} · ${t.designation} · ${t.subjects}`),el('small',`${records.length} monitoring records · ${tasks.length} open actions`));card.append(text,el('span','›','student-arrow'));cards.append(card);}};search.oninput=draw;cl.onchange=draw;draw();}
function renderClassTeacherWatch(){const p=panel('Section CT / Co-CT watch'),body=table(p,['Section','Class teacher','Co-class teacher','Open CT actions','Last review','Review']);for(const[cl,c]of entries(faculty.classes))for(const[sid,s]of entries(draft.classes[cl]?.sections)){const roles=c.roles?.[sid]||{},row=el('tr');cell(row,`${cl}-${s.name}`);for(const field of ['classTeacher','coClassTeacher']){const id=roles[field]?`${cl}:${roles[field]}`:'';const td=cell(row,'');if(id&&staff()[id])td.append(button(staffName(id),()=>go({staff:id})));else td.textContent='Not assigned';}cell(row,entries(mission.tasks).filter(([,t])=>t.category==='class_teacher'&&t.sectionKey===`${cl}:${sid}`&&!['done','cancelled'].includes(t.status)).length);const reviews=entries(mission.records).map(([,r])=>r).filter(r=>r.kind==='class_teacher'&&r.sectionKey===`${cl}:${sid}`).sort((a,b)=>b.date.localeCompare(a.date));cell(row,reviews[0]?.date||'No review recorded');const actions=cell(row,'');for(const[field,label]of [['classTeacher','Review CT'],['coClassTeacher','Review Co-CT']])if(roles[field])actions.append(button(label,()=>editRecord(null,'',`${cl}:${roles[field]}`,'class_teacher',`${cl}:${sid}`)));body.append(row);}}
